package com.example.starter.tf2.domain;

/**
 * 三维平移向量，单位与调用方约定一致（本题为无量纲合成坐标，单位：米）。
 *
 * @param x X 轴分量
 * @param y Y 轴分量
 * @param z Z 轴分量
 */
public record Vec3(double x, double y, double z) {

    /** 零向量。 */
    public static Vec3 ZERO = new Vec3(0.0, 0.0, 0.0);

    /** 向量加法（骨架，后续填充）。 */
    public Vec3 add(Vec3 other) {
        throw new UnsupportedOperationException();
    }

    /** 数乘（骨架，后续填充）。 */
    public Vec3 scale(double s) {
        throw new UnsupportedOperationException();
    }
}

package com.example.starter.tf2.domain;

/**
 * 单位四元数旋转（Hamilton 约定，分量顺序 x,y,z,w）。
 *
 * @param x 虚部 x
 * @param y 虚部 y
 * @param z 虚部 z
 * @param w 实部
 */
public record Quat(double x, double y, double z, double w) {

    /** 恒等旋转。 */
    public static final Quat IDENTITY = new Quat(0.0, 0.0, 0.0, 1.0);

    /** 归一化为单位四元数（骨架）。 */
    public Quat normalized() {
        throw new UnsupportedOperationException();
    }

    /** 四元数乘法 Hamilton 积（骨架）。 */
    public static Quat multiply(Quat a, Quat b) {
        throw new UnsupportedOperationException();
    }

    /** 共轭（单位四元数的逆）（骨架）。 */
    public Quat conjugate() {
        throw new UnsupportedOperationException();
    }

    /** 将四元数作用于向量（骨架）。 */
    public Vec3 rotate(Vec3 v) {
        throw new UnsupportedOperationException();
    }

    /** 球面插值，t=0 取 a，t=1 取 b，自动走短弧（骨架）。 */
    public static Quat slerp(Quat a, Quat b, double t) {
        throw new UnsupportedOperationException();
    }
}

package com.example.starter.tf2.domain;

/**
 * 三维刚体变换 T = (t, q)，表示子坐标系原点在父坐标系中的位姿。
 *
 * @param translation 平移（米）
 * @param rotation    旋转单位四元数
 */
public record RigidTransform(Vec3 translation, Quat rotation) {

    /** 恒等变换。 */
    public static final RigidTransform IDENTITY = new RigidTransform(Vec3.ZERO, Quat.IDENTITY);

    /** 变换复合：返回 this * other（骨架）。 */
    public RigidTransform compose(RigidTransform other) {
        throw new UnsupportedOperationException();
    }

    /** 求逆变换（骨架）。 */
    public RigidTransform inverse() {
        throw new UnsupportedOperationException();
    }
}

