                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, sample.parentFrame());
            ps.setString(2, sample.childFrame());
            ps.setString(3, sample.type().name());
            ps.setLong(4, sample.stampNanos());
